import 'package:cephalopod/features/home/presentation/models/demo_frame_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'demo_ui.freezed.dart';

/// The demo Home plays on a loop: its [frames] in order, and the [still]
/// one, shown alone when the device asks for less motion.
///
/// A UI model (docs/adr/0015): plain data generated by freezed
/// (docs/adr/0011).
@freezed
abstract class DemoUi with _$DemoUi {
  const factory DemoUi({
    required List<DemoFrameUi> frames,
    required DemoFrameUi still,
  }) = _DemoUi;
}
